create table public.daily_checkins (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, local_date date not null, available_minutes integer not null check (available_minutes between 10 and 960), energy smallint not null check (energy between 1 and 5), focus smallint not null check (focus between 1 and 5), intensity text not null check (intensity in ('Recovery','Balanced','Push')), note text check (char_length(note) <= 120), skipped_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,local_date));
create table public.daily_plans (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, local_date date not null, checkin_id uuid references public.daily_checkins(id) on delete set null, status text not null default 'active' check(status in ('active','archived')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,local_date));
create table public.daily_plan_items (id uuid primary key default gen_random_uuid(), plan_id uuid not null references public.daily_plans(id) on delete cascade, quest_id uuid not null references public.quests(id) on delete cascade, lane text not null check(lane in ('now','next','later')), position integer not null check(position >= 0), pinned boolean not null default false, estimated_minutes integer not null check(estimated_minutes > 0), dismissed_at timestamptz, rescheduled_for date, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(plan_id,quest_id), unique(plan_id,lane,position));
create table public.recommendation_overrides (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, plan_id uuid references public.daily_plans(id) on delete cascade, quest_id uuid references public.quests(id) on delete set null, action text not null check(action in ('replace','reorder','pin','dismiss','reschedule')), metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
create table public.inbox_items (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, title text not null check(char_length(trim(title)) between 1 and 160), note text not null default '' check(char_length(note) <= 1000), status text not null default 'open' check(status in ('open','converted','archived')), captured_at timestamptz not null default now(), converted_quest_id uuid references public.quests(id) on delete set null, conversion_key text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,conversion_key), check((status = 'converted') = (converted_quest_id is not null)));
create index daily_checkins_user_date on public.daily_checkins(user_id,local_date desc); create index daily_plans_user_date on public.daily_plans(user_id,local_date desc); create index daily_plan_items_plan_lane on public.daily_plan_items(plan_id,lane,position); create index recommendation_overrides_user_created on public.recommendation_overrides(user_id,created_at desc);
create index inbox_items_user_status on public.inbox_items(user_id,status,captured_at desc);
create trigger daily_checkins_updated_at before update on public.daily_checkins for each row execute function public.set_updated_at(); create trigger daily_plans_updated_at before update on public.daily_plans for each row execute function public.set_updated_at(); create trigger daily_plan_items_updated_at before update on public.daily_plan_items for each row execute function public.set_updated_at();
create trigger inbox_items_updated_at before update on public.inbox_items for each row execute function public.set_updated_at();
alter table public.daily_checkins enable row level security; alter table public.daily_plans enable row level security; alter table public.daily_plan_items enable row level security; alter table public.recommendation_overrides enable row level security;
alter table public.inbox_items enable row level security;
create policy "own checkins" on public.daily_checkins for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy "own plans" on public.daily_plans for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy "own plan items" on public.daily_plan_items for all to authenticated using (exists(select 1 from public.daily_plans p where p.id=plan_id and p.user_id=(select auth.uid()))) with check (exists(select 1 from public.daily_plans p where p.id=plan_id and p.user_id=(select auth.uid()))); create policy "own overrides" on public.recommendation_overrides for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
create policy "own inbox items" on public.inbox_items for all to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);
